const fs=require('fs'),cp=require('child_process'),crypto=require('crypto');
const TARGET=process.env.TARGET_FILE,SHA=process.env.TARGET_SHA,BLOB=process.env.TARGET_BLOB,HASH=process.env.TARGET_HASH,BYTES=Number(process.env.TARGET_BYTES);
const assert=(x,m)=>{if(!x)throw new Error(m)};const sh=c=>cp.execSync(c,{encoding:'utf8'}).trim();
assert(sh('git rev-parse HEAD')===SHA,'wrong parent SHA');assert(sh(`git hash-object ${TARGET}`)===BLOB,'parent blob drift');
const src=fs.readFileSync(TARGET,'utf8');const selector='body:is([data-page="mensagens"], [data-page="comunidade-interna"])\n  :is(.messages-composer, .community-room-composer) {';const start=src.indexOf(selector);assert(start>=0,'target composer rule missing');const end=src.indexOf('\n}',start);assert(end>start,'target composer rule end missing');const block=src.slice(start,end);assert((block.match(/\n  row-gap: 10px;/g)||[]).length===1,'expected source row-gap cardinality drift');const winnerMarker='/* v2.1 — composer draft row guard.';const winnerStart=src.indexOf(winnerMarker);assert(winnerStart>start,'winner section order drift');const winnerSelector=src.indexOf(selector,winnerStart);assert(winnerSelector>winnerStart,'winner selector missing');const winnerEnd=src.indexOf('\n}',winnerSelector);const winnerBlock=src.slice(winnerSelector,winnerEnd);assert((winnerBlock.match(/\n  row-gap: 0;/g)||[]).length===1,'winner row-gap drift');
const out=src.slice(0,start)+block.replace('\n  row-gap: 10px;','')+src.slice(end);fs.writeFileSync(TARGET,out);const stat=sh(`git diff --numstat -- ${TARGET}`).split(/\s+/);assert(stat[0]==='0'&&stat[1]==='1'&&stat[2]===TARGET,`diff drift ${stat.join(' ')}`);const buf=fs.readFileSync(TARGET),hash=crypto.createHash('sha256').update(buf).digest('hex');assert(hash===HASH,`hash drift ${hash}`);assert(buf.length===BYTES,`bytes drift ${buf.length}`);console.log(`PROMOTION BUILD PASS|hash=${hash}|bytes=${buf.length}|files=1|additions=0|deletions=1`);
